let matTex=null, matNrmTex=null, matOrmTex=null, matDamageTex=null, matDetailTex=null;
let matImgAlbedo=null, matImgNormal=null, matImgOrm=null, matImgDamage=null, matImgDetail=null;

/* ---- THE MATERIAL LAYERS ---------------------------------------------------
   Four separate images describe every surface in the game, and each one
   answers a different question the lighting needs to ask:

     DIFFUSE  (matTex)    what colour is this surface
     NORMAL   (matNrmTex) which way is it facing at pixel scale — bevels,
                          rivets, louvres and seams, without geometry
     AO       (ORM.r)     how much of the SKY can this pixel see — darkens the
                          ambient term only, so recesses stay dark even on a
                          face pointing straight at the sun. Multiplying the
                          whole lighting result instead would just look like
                          dirt.
     ROUGH    (ORM.g)     how tight the specular highlight is — the difference
                          between polished trim and cast concrete
     EMISSIVE (ORM.b)     what glows on its own: lamps, vents, energy conduits,
                          lit windows. Unaffected by sun or ambient, which is
                          what makes it still read at night.

   AO, roughness and emissive are single channels, so they pack into one RGBA
   texture and cost a single extra fetch rather than three.                  */

/* ---- NORMAL MAP DERIVATION -------------------------------------------------
   Every bevel, rivet, louvre and panel seam modelled as geometry costs
   vertices on every instance, forever. Baked into a normal map it costs one
   texture fetch and lights identically at command-view zoom — the surface
   still catches the sun along a seam and still shades into a recess, because
   lighting only ever looked at the normal.

   The height field is the albedo tile's own luminance: these are procedural
   surfaces where dark IS recessed (seam lines, bolt shadows, tread gaps) and
   bright IS proud (rivet heads, wear highlights), so the two are already in
   agreement. Sobel it, scale by a per-material relief strength, and pack the
   tangent-space normal into RGB. */
function deriveNormal(srcCtx,S,strength){
  const src=srcCtx.getImageData(0,0,S,S).data;
  const out=srcCtx.createImageData(S,S), d=out.data;
  const L=(x,y)=>{
    const xi=((x%S)+S)%S, yi=((y%S)+S)%S, o=(yi*S+xi)*4;
    return (src[o]*0.299+src[o+1]*0.587+src[o+2]*0.114)/255;
  };
  for(let y=0;y<S;y++) for(let x=0;x<S;x++){
    // Sobel on a wrapped lookup, so the normal map tiles as cleanly as the albedo
    const gx=(L(x+1,y-1)+2*L(x+1,y)+L(x+1,y+1))-(L(x-1,y-1)+2*L(x-1,y)+L(x-1,y+1));
    const gy=(L(x-1,y+1)+2*L(x,y+1)+L(x+1,y+1))-(L(x-1,y-1)+2*L(x,y-1)+L(x+1,y-1));
    let nx=-gx*strength, ny=-gy*strength, nz=1;
    const l=Math.hypot(nx,ny,nz)||1;
    const o=(y*S+x)*4;
    d[o]  =(nx/l*0.5+0.5)*255;
    d[o+1]=(ny/l*0.5+0.5)*255;
    d[o+2]=(nz/l*0.5+0.5)*255;
    d[o+3]=255;
  }
  return out;
}
