    c.fillStyle='#253648'; c.fillRect(0,0,S,S);
    mtVNoise(c,S,12,0.035);
    c.strokeStyle='rgba(104,218,245,.62)'; c.lineWidth=5;
    c.beginPath(); c.moveTo(0,S*.50); c.lineTo(S*.36,S*.50);
    c.lineTo(S*.44,S*.38); c.lineTo(S*.72,S*.38);
    c.lineTo(S*.80,S*.50); c.lineTo(S,S*.50); c.stroke();
    c.strokeStyle='rgba(10,18,28,.75)'; c.lineWidth=3;
    c.strokeRect(18,18,S-36,S-36);
