  // ---- biome detail -------------------------------------------------------
  const groundTile=(color,noise)=>((c,S)=>{ c.fillStyle=color;c.fillRect(0,0,S,S);mtVNoise(c,S,noise||18,.08); });
  tile(MAT.ICE_PACK,groundTile('#315c8a',18));
