  tile(MAT.BASALT_CRUST,groundTile('#34343b',22));
  tile(MAT.LAVA_FISSURE,(c,S)=>{ c.fillStyle='#34272a';c.fillRect(0,0,S,S);c.strokeStyle='#e25a2e';c.lineWidth=5;for(let x=-S;x<S*2;x+=42){c.beginPath();c.moveTo(x,0);c.lineTo(x+S*.35,S);c.stroke();} });
  tile(MAT.SULFUR_ASH,groundTile('#918652',16));
  tile(MAT.SAND_DUNE,(c,S)=>{c.fillStyle='#c9a66b';c.fillRect(0,0,S,S);for(let y=8;y<S;y+=18){c.strokeStyle='rgba(255,240,180,.16)';c.beginPath();c.moveTo(0,y);c.quadraticCurveTo(S*.5,y-5,S,y);c.stroke();}});
  tile(MAT.CANYON_ROCK,(c,S)=>{c.fillStyle='#895849';c.fillRect(0,0,S,S);for(let y=12;y<S;y+=28){c.strokeStyle='rgba(50,24,20,.4)';c.lineWidth=4;c.beginPath();c.moveTo(0,y);c.lineTo(S,y+Math.sin(y)*7);c.stroke();}});
