  tile(MAT.MOSSY_BOULDER,(c,S)=>{c.fillStyle='#65665c';c.fillRect(0,0,S,S);mtVNoise(c,S,12,.12);c.fillStyle='rgba(80,140,70,.38)';c.fillRect(0,S*.55,S,S*.45);});
